InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_StepTimeOUT_For_FBs
VAR_INPUT	
	iStep						:UINT;
	sStepStatus					:STRING;
	tTimeOut					:TIME:=	T#5S;		
	bEnable						:BOOL;	
	bResetERROR					:BOOL;
	arrExceptions				:ARRAY[0..20] OF UINT;		
END_VAR
VAR_OUTPUT	
	bERROR						:BOOL;
	sERROR						:STRING(255);
END_VAR
VAR
	iStepArchive				:UINT;		
	bStartTimer					:BOOL;		
	i							:UINT;		
	bException					:BOOL;			
	tonTimeOut					:TON;
	sStepTimeOutERROR_Temp		:STRING[255]:='Step Timeout ERROR';
END_VAR

FUNCTION_BLOCK FB_StepTimeOUT_For_FBs
VAR_INPUT	
	iStep						:UINT;
	sStepStatus					:STRING;
	tTimeOut					:TIME:=	T#5S;		
	bEnable						:BOOL;	
	bResetERROR					:BOOL;
	arrExceptions				:ARRAY[0..20] OF UINT;		
END_VAR
VAR_OUTPUT	
	bERROR						:BOOL;
	sERROR						:STRING(255);
END_VAR
VAR
	iStepArchive				:UINT;		
	bStartTimer					:BOOL;		
	i							:UINT;		
	bException					:BOOL;			
	tonTimeOut					:TON;
	sStepTimeOutERROR_Temp		:STRING[255]:='Step Timeout ERROR';
END_VAR

FUNCTION_BLOCK FB_StepTimeOUT_For_FBs
VAR_INPUT	
	iStep						:UINT;
	sStepStatus					:STRING;
	tTimeOut					:TIME:=	T#5S;		
	bEnable						:BOOL;	
	bResetERROR					:BOOL;
	arrExceptions				:ARRAY[0..20] OF UINT;		
END_VAR
VAR_OUTPUT	
	bERROR						:BOOL;
	sERROR						:STRING(255);
END_VAR
VAR
	iStepArchive				:UINT;		
	bStartTimer					:BOOL;		
	i							:UINT;		
	bException					:BOOL;			
	tonTimeOut					:TON;
	sStepTimeOutERROR_Temp		:STRING[255]:='Step Timeout ERROR';
END_VAR

ST.xhtml:
IF bEnable THEN

    IF NOT  bERROR THEN
        // Exception?
        bException := FALSE;
        i := 0;
        FOR i := 0 TO 20 DO
            IF arrExceptions[i] = iStep THEN // ha tömb egyetlen eleme megegyezik az aktuális lépéssel akkor az kivétel
                bException := TRUE;
            END_IF;
        END_FOR;


        // NEW Step???
        IF iStep <> iStepArchive THEN
            iStepArchive := iStep;
            bStartTimer := FALSE;
        ELSIF NOT bException THEN
            bStartTimer := TRUE;
        END_IF;

    END_IF;

    // Start TimeOut
    tonTimeOut(IN := bStartTimer,
                    PT :=tTimeOut);

    //TimeOut ERROR
    IF tonTimeOut.Q THEN
        bERROR := TRUE;
        sERROR := CONCAT(sStepTimeOutERROR_Temp,CONCAT('  STEP: ' ,CONCAT(INT_TO_STRING(iStep),CONCAT(': ',sStepStatus))));
        bStartTimer := FALSE;
    END_IF;
END_IF;

  // RESET ERROR
IF bResetERROR
    OR NOT bEnable THEN
   		bERROR := FALSE;
     	sERROR := '';
    	iStepArchive := 0;
END_IF;

bERROR;
sERROR;
arrExceptions[0];
arrExceptions[1];
arrExceptions[2];
arrExceptions[3];
arrExceptions[4];
arrExceptions[5];
arrExceptions[6];
arrExceptions[7];
arrExceptions[8];
arrExceptions[9];
arrExceptions[10];
arrExceptions[11];
arrExceptions[12];
arrExceptions[13];
arrExceptions[14];
arrExceptions[15];
arrExceptions[16];
arrExceptions[17];
arrExceptions[18];
arrExceptions[19];
arrExceptions[20];

